@import "tailwindcss";

@theme {
  --color-cream: #fbf7f2;
  --color-sage: #7f9c86;
  --color-sage-dark: #5d7a64;
  --color-blush: #f2d6cf;
  --color-ink: #3a3532;
  --color-muted: #8a817b;
  --font-sans: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
}

body {
  background: var(--color-cream);
  color: var(--color-ink);
  -webkit-tap-highlight-color: transparent;
}

@utility btn {
  @apply inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 font-semibold transition active:scale-[0.98] disabled:opacity-50;
}
@utility btn-primary {
  @apply btn bg-sage text-white hover:bg-sage-dark;
}
@utility btn-ghost {
  @apply btn border border-ink/15 bg-white text-ink hover:bg-white/70;
}
@utility card {
  @apply rounded-3xl bg-white p-5 shadow-[0_2px_20px_rgba(58,53,50,0.06)];
}
@utility chip {
  @apply rounded-full border border-sage/40 bg-white px-4 py-2 text-sm text-sage-dark transition hover:bg-sage hover:text-white;
}
import type { Metadata, Viewport } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "Calm Registry",
  description: "A baby registry that builds itself from a short, friendly chat.",
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: "#fbf7f2",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body className="min-h-dvh antialiased">
        <div className="mx-auto min-h-dvh max-w-xl px-4 pb-16">{children}</div>
      </body>
    </html>
  );
}
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { api, authEnabled, getBrowserSupabase } from "@/lib/client";

type Summary = { id: string; slug: string; title: string };

export default function Home() {
  const [registries, setRegistries] = useState<Summary[]>([]);

  useEffect(() => {
    void (async () => {
      if (authEnabled) {
        const { data } = await getBrowserSupabase()!.auth.getSession();
        if (!data.session) return;
      }
      const result = await api<{ registries: Summary[] }>("/api/registries").catch(() => null);
      if (result) setRegistries(result.registries);
    })();
  }, []);

  return (
    <main className="space-y-8 pt-16">
      <div className="space-y-4 text-center">
        <p className="text-5xl">🌿</p>
        <h1 className="text-3xl font-bold leading-tight">Your baby registry, without the overwhelm.</h1>
        <p className="text-lg text-muted">
          Chat for about 3 minutes. We&apos;ll build a complete registry from Amazon, Target, and Walmart. Then you
          just review it, one small step at a time.
        </p>
      </div>

      <Link href="/start" className="btn-primary w-full text-lg">
        Start my registry
      </Link>

      <ul className="space-y-3 text-muted">
        <li>✓ No blank pages. You get a full draft right away.</li>
        <li>✓ Each item tells you why it&apos;s there.</li>
        <li>✓ Review one category at a time, about 2 minutes each.</li>
        <li>✓ Change anything by just saying it: &ldquo;make it cheaper.&rdquo;</li>
      </ul>

      {registries.length > 0 && (
        <section className="space-y-3">
          <h2 className="font-semibold">Pick up where you left off</h2>
          {registries.map((r) => (
            <Link key={r.id} href={`/registry/${r.id}`} className="card block font-medium hover:bg-white/70">
              {r.title} →
            </Link>
          ))}
        </section>
      )}
    </main>
  );
}
