"use client";

import { CATEGORY_ICONS, formatPrice, PRIORITY_LABELS } from "@/lib/client";
import { RETAILER_LABELS, type RegistryItem } from "@/lib/types";

const PRIORITY_STYLES = {
  "must-have": "bg-sage/15 text-sage-dark",
  "nice-to-have": "bg-blush text-ink",
  later: "bg-ink/5 text-muted",
} as const;

export function ItemCard({
  item,
  onChooseOffer,
  children,
}: {
  item: RegistryItem;
  onChooseOffer?: (offerId: string) => void;
  children?: React.ReactNode;
}) {
  const [primary, ...alternatives] = item.offers;
  return (
    <article className="card space-y-4">
      <div className="flex items-start gap-4">
        <div className="flex h-20 w-20 shrink-0 items-center justify-center overflow-hidden rounded-2xl bg-cream text-4xl">
          {primary?.imageUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={primary.imageUrl} alt="" className="h-full w-full object-contain" />
          ) : (
            CATEGORY_ICONS[item.category]
          )}
        </div>
        <div className="min-w-0 flex-1 space-y-1">
          <span className={`inline-block rounded-full px-2.5 py-0.5 text-xs font-medium ${PRIORITY_STYLES[item.priority]}`}>
            {PRIORITY_LABELS[item.priority]}
          </span>
          <h3 className="text-lg font-semibold leading-snug">
            {item.name}
            {item.qty > 1 && <span className="font-normal text-muted"> × {item.qty}</span>}
          </h3>
          <p className="text-sm text-muted">{item.reason}</p>
        </div>
      </div>

      {primary && (
        <a
          href={primary.url}
          target="_blank"
          rel="noopener noreferrer sponsored"
          className="flex items-center justify-between gap-3 rounded-2xl bg-cream px-4 py-3 text-sm"
        >
          <span className="min-w-0 truncate">{primary.title}</span>
          <span className="shrink-0 font-semibold">
            {formatPrice(primary.price)} · {RETAILER_LABELS[primary.retailer]}
          </span>
        </a>
      )}

      {onChooseOffer && alternatives.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {alternatives.map((offer) => (
            <button key={offer.id} className="chip text-xs" onClick={() => onChooseOffer(offer.id)}>
              Also at {RETAILER_LABELS[offer.retailer]} {offer.price !== null && `for ${formatPrice(offer.price)}`}
            </button>
          ))}
        </div>
      )}

      {children}
    </article>
  );
}
  }

  if (building) {
    return (
      <div className="flex min-h-dvh flex-col items-center justify-center gap-4 text-center">
        <div className="h-12 w-12 animate-spin rounded-full border-4 border-sage/30 border-t-sage" />
        <h2 className="text-xl font-semibold">Building your registry…</h2>
        <p className="text-muted">Comparing Amazon, Target, and Walmart for you. This takes about 30 seconds.</p>
      </div>
    );
  }

  const answered = messages.filter((m) => m.role === "user").length;

  return (
    <div className="flex min-h-dvh flex-col pt-6">
      <header className="mb-4 flex items-center justify-between">
        <span className="text-sm text-muted">About {Math.max(1, 8 - answered)} quick questions left</span>
        <button onClick={restart} className="text-sm text-muted underline">
          Start over
        </button>
      </header>

      <div className="flex-1 space-y-3">
        {messages.map((m, i) => (
          <div key={i} className={m.role === "user" ? "flex justify-end" : "flex"}>
            <p
              className={
                m.role === "user"
                  ? "max-w-[80%] rounded-3xl rounded-br-md bg-sage px-4 py-3 text-white"
                  : "max-w-[85%] rounded-3xl rounded-bl-md bg-white px-4 py-3 shadow-sm"
              }
            >
              {m.content}
            </p>
          </div>
        ))}
        {thinking && <p className="px-2 text-muted">…</p>}
        {error && (
          <p className="text-sm text-red-600">
            {error}{" "}
            <button className="underline" onClick={() => void send(messages)}>
              Retry
            </button>
          </p>
        )}
        <div ref={bottom} />
      </div>

      <div className="sticky bottom-0 space-y-3 bg-cream pt-3 pb-4">
        {chips.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {chips.map((chip) => (
              <button key={chip} className="chip" onClick={() => answer(chip)} disabled={thinking}>
                {chip}
              </button>
            ))}
          </div>
        )}
        <form
          onSubmit={(e) => {
            e.preventDefault();
            answer(input);
          }}
          className="flex gap-2"
        >
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Or type anything…"
            className="flex-1 rounded-full border border-ink/15 bg-white px-5 py-3 outline-none focus:border-sage"
          />
          <button className="btn-primary" disabled={thinking || !input.trim()}>
            Send
          </button>
        </form>
      </div>
    </div>
  );
}
        if (!items.length) return null;
        return (
          <section key={category} className="space-y-3">
            <h2 className="text-lg font-semibold">
              {CATEGORY_ICONS[category]} {category}
            </h2>
            {items.map((item) => (
              <GiftCard key={item.id} item={item} slug={slug} onBought={load} />
            ))}
          </section>
        );
      })}
    </main>
  );
}

function GiftCard({ item, slug, onBought }: { item: RegistryItem; slug: string; onBought: () => Promise<void> }) {
  const [confirming, setConfirming] = useState<RetailerId | "elsewhere" | null>(null);
  const [name, setName] = useState("");
  const [error, setError] = useState("");
  const primary = item.offers[0];

  async function markBought() {
    setError("");
    const response = await fetch(`/api/r/${slug}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ itemId: item.id, buyerName: name, retailer: confirming === "elsewhere" ? null : confirming }),
    });
    const data = (await response.json()) as { error?: string };
    if (!response.ok) setError(data.error ?? "That didn't work.");
    setConfirming(null);
    await onBought();
  }

  return (
    <article className={`card space-y-3 ${item.purchased ? "opacity-60" : ""}`}>
      <div className="flex items-start gap-4">
        <div className="flex h-16 w-16 shrink-0 items-center justify-center overflow-hidden rounded-2xl bg-cream text-3xl">
          {primary?.imageUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={primary.imageUrl} alt="" className="h-full w-full object-contain" />
          ) : (
            CATEGORY_ICONS[item.category]
          )}
        </div>
        <div className="min-w-0 flex-1">
          <p className="text-xs text-muted">{PRIORITY_LABELS[item.priority]}</p>
          <h3 className="font-semibold">
            {item.name}
            {item.qty > 1 && <span className="font-normal text-muted"> × {item.qty}</span>}
          </h3>
          <p className="truncate text-sm text-muted">{primary?.title}</p>
        </div>
      </div>

      {item.purchased ? (
        <p className="text-center font-medium text-sage-dark">🎁 Already gifted</p>
      ) : confirming ? (
        <div className="space-y-2 rounded-2xl bg-cream p-3">
          <p className="text-sm">Did you buy it? Let them know so nobody doubles up.</p>
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Your name (optional)"
            className="w-full rounded-full border border-ink/15 bg-white px-4 py-2 outline-none focus:border-sage"
          />
          <div className="flex gap-2">
            <button className="btn-ghost flex-1" onClick={() => setConfirming(null)}>
              Not yet
            </button>
            <button className="btn-primary flex-1" onClick={() => void markBought()}>
              Yes, I bought it
            </button>
          </div>
        </div>
      ) : (
        <div className="flex flex-wrap gap-2">
          {item.offers.map((offer) => (
            <a
              key={offer.id}
              href={offer.url}
              target="_blank"
              rel="noopener noreferrer sponsored"
              onClick={() => setConfirming(offer.retailer)}
              className="chip"
            >
              {RETAILER_LABELS[offer.retailer]} · {formatPrice(offer.price)}
            </a>
          ))}
          <button className="text-sm text-muted underline" onClick={() => setConfirming("elsewhere")}>
            Bought it elsewhere
          </button>
        </div>
      )}
      {error && <p className="text-sm text-red-600">{error}</p>}
    </article>
  );
}

