# Target Partners (Impact) tracking link base, e.g. https://goto.target.com/c/<pid>/<adid>/2092
TARGET_IMPACT_LINK=
import type { Offer, RetailerId } from "../types";

export type SearchFilters = { maxPrice?: number };

export interface RetailerProvider {
  id: RetailerId;
  /** True when real credentials are present; otherwise the mock is used. */
  isConfigured(): boolean;
  search(query: string, filters: SearchFilters): Promise<Offer[]>;
}
import "server-only";
import type { Offer, RetailerId } from "../types";
import { amazonProvider } from "./amazon";
import { mockSearch } from "./mock";
import type { RetailerProvider, SearchFilters } from "./provider";
import { targetProvider } from "./target";
import { walmartProvider } from "./walmart";

const PROVIDERS: RetailerProvider[] = [amazonProvider, walmartProvider, targetProvider];
const TIMEOUT_MS = 6000;
const MAX_OFFERS = 4;

function withTimeout<T>(promise: Promise<T>, ms: number) {
  return Promise.race([
    promise,
    new Promise<never>((_, reject) => setTimeout(() => reject(new Error("timeout")), ms)),
  ]);
}

function normalize(title: string) {
  return title.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim().split(" ").slice(0, 6).join(" ");
}

async function searchProvider(provider: RetailerProvider, query: string, filters: SearchFilters) {
  if (!provider.isConfigured()) return mockSearch(provider.id, query, filters.maxPrice);
  try {
    return await withTimeout(provider.search(query, filters), TIMEOUT_MS);
  } catch (error) {
    console.warn(`[retail] ${provider.id} search failed for "${query}"`, error);
    return [];
  }
}

function score(offer: Offer, preferred: RetailerId[]) {
  const preference = preferred.includes(offer.retailer) ? 2 : 0;
  const rating = offer.rating ?? 4;
  const stock = offer.inStock ? 0 : -5;
  return preference + rating + stock;
}

/** Search every retailer, then interleave so each store's best match surfaces. */
export async function findOffers(query: string, preferred: RetailerId[], filters: SearchFilters = {}) {
  const results = await Promise.all(PROVIDERS.map((p) => searchProvider(p, query, filters)));
  const seen = new Set<string>();
  const perRetailer = results.map((offers) =>
    offers
      .filter((o) => {
        const key = `${o.retailer}:${normalize(o.title)}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .sort((a, b) => score(b, preferred) - score(a, preferred)),
  );

  const firsts = perRetailer.flatMap((offers) => offers.slice(0, 1));
  const rest = perRetailer.flatMap((offers) => offers.slice(1));
  firsts.sort((a, b) => score(b, preferred) - score(a, preferred));
  rest.sort((a, b) => score(b, preferred) - score(a, preferred));
  return [...firsts, ...rest].slice(0, MAX_OFFERS);
}

export async function mapLimit<T, R>(items: T[], limit: number, fn: (item: T) => Promise<R>) {
  const out: R[] = new Array(items.length);
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.min(limit, items.length) }, async () => {
      while (next < items.length) {
        const index = next++;
        out[index] = await fn(items[index]);
      }
    }),
  );
  return out;
}

export function liveRetailers() {
  return PROVIDERS.filter((p) => p.isConfigured()).map((p) => p.id);
}
import { createHash, createHmac } from "node:crypto";
import type { Offer } from "../types";
import type { RetailerProvider } from "./provider";

const HOST = "webservices.amazon.com";
const REGION = "us-east-1";
const SERVICE = "ProductAdvertisingAPI";
const PATH = "/paapi5/searchitems";
const TARGET = "com.amazon.paapi5.v1.ProductAdvertisingAPIv1.SearchItems";

function sha256(value: string) {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function hmac(key: Buffer | string, value: string) {
  return createHmac("sha256", key).update(value, "utf8").digest();
}

function signHeaders(body: string, accessKey: string, secretKey: string) {
  const amzDate = new Date().toISOString().replace(/[:-]|\.\d{3}/g, "");
  const dateStamp = amzDate.slice(0, 8);
  const headers: Record<string, string> = {
    "content-encoding": "amz-1.0",
    "content-type": "application/json; charset=utf-8",
    host: HOST,
    "x-amz-date": amzDate,
    "x-amz-target": TARGET,
  };
  const signedHeaders = Object.keys(headers).sort().join(";");
  const canonicalHeaders = Object.keys(headers)
    .sort()
    .map((k) => `${k}:${headers[k]}\n`)
    .join("");
  const canonicalRequest = ["POST", PATH, "", canonicalHeaders, signedHeaders, sha256(body)].join("\n");
  const scope = `${dateStamp}/${REGION}/${SERVICE}/aws4_request`;
  const stringToSign = ["AWS4-HMAC-SHA256", amzDate, scope, sha256(canonicalRequest)].join("\n");
  const signingKey = hmac(hmac(hmac(hmac(`AWS4${secretKey}`, dateStamp), REGION), SERVICE), "aws4_request");
  const signature = createHmac("sha256", signingKey).update(stringToSign, "utf8").digest("hex");
  headers.authorization = `AWS4-HMAC-SHA256 Credential=${accessKey}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
  return headers;
}

type PaapiItem = {
  ASIN: string;
  DetailPageURL: string;
  ItemInfo?: { Title?: { DisplayValue?: string } };
  Images?: { Primary?: { Medium?: { URL?: string } } };
  Offers?: { Listings?: Array<{ Price?: { Amount?: number }; Availability?: { Type?: string } }> };
  CustomerReviews?: { StarRating?: { Value?: number } };
};

export const amazonProvider: RetailerProvider = {
  id: "amazon",
  isConfigured() {
    return Boolean(
      process.env.AMAZON_PAAPI_ACCESS_KEY && process.env.AMAZON_PAAPI_SECRET && process.env.AMAZON_PARTNER_TAG,
    );
  },
  async search(query, filters) {
    const body = JSON.stringify({
      Keywords: query,
      SearchIndex: "Baby",
      ItemCount: 3,
      PartnerTag: process.env.AMAZON_PARTNER_TAG,
      PartnerType: "Associates",
      Marketplace: "www.amazon.com",
      ...(filters.maxPrice ? { MaxPrice: Math.round(filters.maxPrice * 100) } : {}),
      Resources: [
        "ItemInfo.Title",
        "Images.Primary.Medium",
        "Offers.Listings.Price",
        "Offers.Listings.Availability.Type",
        "CustomerReviews.StarRating",
      ],
    });
    const response = await fetch(`https://${HOST}${PATH}`, {
      method: "POST",
      headers: signHeaders(body, process.env.AMAZON_PAAPI_ACCESS_KEY!, process.env.AMAZON_PAAPI_SECRET!),
      body,
    });
import type { Offer, RetailerId } from "../types";

const SEARCH_URLS: Record<RetailerId, (q: string) => string> = {
  amazon: (q) => `https://www.amazon.com/s?k=${encodeURIComponent(q)}`,
  walmart: (q) => `https://www.walmart.com/search?q=${encodeURIComponent(q)}`,
  target: (q) => `https://www.target.com/s?searchTerm=${encodeURIComponent(q)}`,
};

const BRANDS = ["Little Lark", "Cozy Sprout", "Bramble & Bee", "Nestwell", "Puddle Duck"];

// Checked in order, so accessory words ("sheets", "mirror") win over the big item they mention.
const PRICE_HINTS: Array<[RegExp, number]> = [
  [/sheet|diaper|wipe|onesie|bodysuit|sock|burp|bib|pacifier|clipper|cream|wash|brush|towel|mirror|book/i, 18],
  [/swaddle|sleep sack|bottle|bath|diaper bag|thermometer|aspirator|sleeper/i, 35],
  [/mattress|bassinet|monitor|high chair|pump|carrier|play ?yard|humidifier|bouncer/i, 110],
  [/stroller|car seat|crib|glider|travel system/i, 220],
];

function hash(value: string) {
  let h = 2166136261;
  for (const c of value) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return Math.abs(h);
}

export function mockSearch(retailer: RetailerId, query: string, maxPrice?: number): Offer[] {
  const base = PRICE_HINTS.find(([pattern]) => pattern.test(query))?.[1] ?? 28;
  return [0, 1].map((variant) => {
    const seed = hash(`${retailer}:${query}:${variant}`);
    const brand = BRANDS[seed % BRANDS.length];
    let price = Math.round(base * (0.7 + (seed % 60) / 100)) - 0.01;
    if (maxPrice && price > maxPrice) price = Math.max(4.99, Math.floor(maxPrice) - 0.01);
    return {
      retailer,
      externalId: `mock-${seed.toString(36)}`,
      title: `${brand} ${query.replace(/\b\w/g, (c) => c.toUpperCase())}`,
      price,
      imageUrl: null,
      url: SEARCH_URLS[retailer](query),
      rating: 4 + (seed % 10) / 10,
      inStock: true,
    };
  });
}
